});

// Only run these tests if the response is valid JSON
if (pm.response.headers.get("Content-Type") && pm.response.headers.get("Content-Type").includes("application/json")) {
    let response = pm.response.json();

    // 2. Verify totalprice was updated
    pm.test("Total price updated to 2500", function () {
        pm.expect(response.totalprice).to.eql(2500);
